// pli
// → Array of objects containing selected plan IDs and their corresponding product IDs.
// → This data is fetched from the search query API response.

// 📌 Inside each pli object:
// plid
// → Type: String
// → Description: Unique identifier for the selected plan.
// → Example: isid8037318205_1_seniorcitizen
// → Source: Comes from the search query response.

// pi
// → Type: Array of objects
// → Description: List of product IDs associated with the selected plan.

// 📌 Inside each pi object:
// pid
// → Type: String
// → Description: Unique identifier for a specific product under the selected plan.
// → Example:

// "ABHI-PLAN_100-WW-AAI-BOXX" (drive from search response)

// {{seniorCitizenProductId}} (Postman variable placeholder)
{
    "pli": [
        {
            "plid": "isid6552236869_0_regular",
            "pi": [
                {
                    "pid": "ABHI-PLAN_100-WW-AAI-BOXX"
                }
            ]
        }
    ]
}

